#' Base Agent
#' Abstract base class for all specialized agents.
#' @export
BaseAgent <- R6::R6Class('BaseAgent', public = list(config = NULL, llm_service = NULL, state = 'idle', memory = NULL, start_time = NULL, task_count = 0, request_timestamps = c(), token_usage = 0, daily_requests = 0, performance_metrics = list(response_time = c(), token_usage = c(), success_rate = c()), initialize = function(config, llm_service = NULL) { self <- config; self <- llm_service; self <- AgentMemory(); self <- list(response_time = c(), token_usage = c(), success_rate = c()) }, initialize_agent = function() { self <- 'idle'; self <- Sys.time(); private() }, shutdown = function() { self <- 'idle'; private() }, get_uptime = function() { if (!is.null(self)) return(as.numeric(difftime(Sys.time(), self, units = 'secs'))); return(NULL) }, check_rate_limit = function(estimated_tokens = 1000) { now <- Sys.time(); one_minute_ago <- as.numeric(now) - 60; self <- self[as.numeric(self) > one_minute_ago]; if (length(self) >= self) return(FALSE); return(TRUE) }, record_request = function(tokens_used) { self <- c(self, Sys.time()); self <- self + tokens_used; self <- self + 1 }, get_performance_summary = function() { list(name = self, state = self, uptime_seconds = self(), total_tasks = self, daily_requests = self, patterns_stored = length(self), improvements_stored = length(self)) }, execute_with_retry = function(task_func, max_retries = 3, delay = 1, ...) { last_error <- NULL; for (attempt in seq_len(max_retries)) { tryCatch({ result <- task_func(...); self <- self + 1; return(result) }, error = function(e) { last_error <- e; if (attempt < max_retries) Sys.sleep(delay * attempt) }) }; return(TaskResult(success = FALSE, errors = list(paste('Task failed:', last_error)))) }, execute_task = function(task) stop('execute_task() must be implemented by subclasses'), analyze_performance = function() stop('analyze_performance() must be implemented by subclasses'), suggest_improvements = function() stop('suggest_improvements() must be implemented by subclasses')), private = list(load_memory = function() { memory_path <- file.path('agents/memory', paste0(tolower(self), '_memory.json')); if (file.exists(memory_path)) tryCatch(self(memory_path), error = function(e) {}) }, save_memory = function() { memory_path <- file.path('agents/memory', paste0(tolower(self), '_memory.json')); dir.create(dirname(memory_path), recursive = TRUE, showWarnings = FALSE); tryCatch(self(memory_path), error = function(e) {}) }))
